-- ----------------------------
-- Table structure for buff_requests
-- ----------------------------
DROP TABLE IF EXISTS `buff_requests`;
CREATE TABLE `buff_requests`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `player_id` int NOT NULL COMMENT 'ID of the player receiving the item',
  `player_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Name of the player',
  `item_id` int NOT NULL COMMENT 'ID of the item from item_template',
  `options_string` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT 'Item options in format: optionId-param;optionId-param (e.g., 50-20;30-1)',
  `quantity` int NOT NULL DEFAULT 1 COMMENT 'Number of items to buff',
  `status` enum('pending','completed','failed') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending' COMMENT 'Request status',
  `admin_id` int NOT NULL COMMENT 'ID of admin who created the request',
  `admin_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Name of admin who created the request',
  `result_message` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT 'Result message after processing (success or error)',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp COMMENT 'When the request was created',
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT 'When the request was last updated',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_player_id`(`player_id` ASC) USING BTREE,
  INDEX `idx_admin_id`(`admin_id` ASC) USING BTREE,
  INDEX `idx_created_at`(`created_at` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'Stores buff item requests with pending/completed/failed status' ROW_FORMAT = DYNAMIC;

