INSERT INTO `cvh_baiviet` VALUES (17, 'Ngọc Rồng Akaya', '<p><span style=\"color: rgb(185, 106, 217);\"><em><strong>Ch&agrave;o mừng </strong></em></span><span style=\"font-family: georgia, palatino, serif;\"><em><span style=\"color: rgb(0, 0, 0);\">, Admin Ngọc Rồng Akaya</span></em></span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: 18pt; color: rgb(185, 106, 217); font-family: \'courier new\', courier, monospace;\"><em><strong>NGOC RONG AKAYA</strong></em></span></p>\r\n<p><span style=\"font-family: georgia, palatino, serif;\"><em><span style=\"color: rgb(0, 0, 0);\">------------------------------------</span></em></span></p>\r\n<p><span style=\"font-family: georgia, palatino, serif;\"><em><span style=\"color: rgb(0, 0, 0);\">&nbsp;</span></em></span></p>\r\n<p><span style=\"font-family: georgia, palatino, serif;\"><em><span style=\"color: rgb(0, 0, 0);\"><span style=\"color: rgb(224, 62, 45);\"><strong>Giftcode</strong></span>&nbsp;<span style=\"color: rgb(224, 62, 45);\"><strong>:</strong></span>&nbsp;tanthu, hotro, akaya, test, day1</span></em></span></p>\r\n<p><span style=\"font-family: georgia, palatino, serif;\"><em><span style=\"color: rgb(0, 0, 0);\">( Nhập code tại NPC Santa ở Đảo Kame)</span></em></span></p>\r\n<p><span style=\"font-family: georgia, palatino, serif;\"><em><span style=\"color: rgb(0, 0, 0);\"><strong><span style=\"color: rgb(224, 62, 45);\">Note : </span></strong>hi&ecirc;n bản Beta n&ecirc;n anh em c&oacute; lỗi g&igrave; vui l&ograve;ng b&aacute;o lại cho admin&nbsp;</span></em></span></p>\r\n<p><span style=\"font-family: georgia, palatino, serif;\"><em><span style=\"color: rgb(0, 0, 0);\"><strong><span style=\"color: rgb(224, 62, 45);\">Note :</span></strong></span></em><span style=\"color: rgb(0, 0, 0);\"><strong><span style=\"color: rgb(224, 62, 45);\">&nbsp;</span></strong><span style=\"color: rgb(0, 0, 0);\">c</span>&aacute;c </span><em><span style=\"color: rgb(0, 0, 0);\">cải trang v&agrave; phụ kiện vip đẹp sẽ ra mắt sau