INSERT INTO `item_template` VALUES (1399, 27, 3, 'Cần câu cá', 'Chất liệu: Trúc nguyên cây nhập khẩu từ Đông Lào, dây cước bện từ polime tổng hợp nhập khẩu từ Wibuland, lưỡi thép nguyên chất nhập khẩu từ Mẽo. Cân kèo mọi loại cá.', 16114, 0, 1, 0, 0, 0, -1, -1, -1);
INSERT INTO `item_template` VALUES (1400, 75, 3, 'Mồi câu cá', 'Giun này thì đào quanh mấy tảng đá là có, nhìn thì phèn nhưng ngon phết cho cá ăn thì hơi phí :>', 16115, 0, 1, 0, 0, 0, -1, -1, -1);
INSERT INTO `item_template` VALUES (1401, 37, 3, 'Cá cờ cam', 'Loại 4:Cá nhỏ, vảy ngắn, vân vàng cam. Khá phổ biến ở mọi nơi', 16116, 0, 1, 0, 0, 0, -1, -1, -1);
INSERT INTO `item_template` VALUES (1402, 37, 3, 'Cá rô phi', 'Loại 4:Cá nhỏ, vảy cứng, có gai lưng, vây màu tím khá lạ, cũng phổ biến nhưng được cái ăn ngon phết', 16117, 0, 1, 0, 0, 0, -1, -1, -1);
INSERT INTO `item_template` VALUES (1403, 38, 3, 'Cá chép vàng', 'Loại 3:Cá cỡ trung, vảy mềm, thân thon dài, vây vàng rực rỡ, giá trị làm cảnh cao và nấu dưa ăn cũng ngon phết', 16118, 0, 1, 0, 0, 0, -1, -1, -1);
INSERT INTO `item_template` VALUES (1404, 38, 3, 'Cá chim xanh', 'Loại 3:Cá cỡ trung, vảy cứng, thân bầu dục, ăn tạp, răng sắc cắn rất đau. Sát thủ cắn bi những ai bơi ở khu nó sống', 9595, 0, 1, 0, 0, 0, -1, -1, -1);
INSERT INTO `item_template` VALUES (1405, 38, 3, 'Cá mú', 'Loại 3:Cá cỡ trung, vảy mềm , đầu to , thân thon, nhìn thì xấu nhưng ăn ngon vãi đái', 9596, 0, 1, 0, 0, 0, -1, -1, -1);
INSERT INTO `item_template` VALUES (1406, 40, 3, 'Cá heo xanh', 'Loại 1: Cá cỡ lớn, không vảy, thân thon dài, thông minh, nhưng hay hấp diêm tập thể những con cái trong bầy', 9608, 0, 1, 0, 0, 0, -1, -1, -1);
INSERT INTO `item_template` VALUES (1407, 39, 3, 'Cua hoàng đế', 'Loại 2:Động vật giáp xác chân đốt, càng rất sắc nhưng chứa rất nhiều thịt, giá trị cao', 9621, 0, 1, 0, 0, 0, -1, -1, -1);
INSERT INTO `item_template` VALUES (1408, 40, 3, 'Ôc hương', 'Loại 4:Ôc hiếm ở vùng biển sâu, vỏ cứng như kim cương nhưng bên trong là thịt ốc ngon vcl', 9602, 0, 1, 0, 0, 0, -1, -1, -1);
INSERT INTO `item_template` VALUES (1409, 39, 3, 'Rùa ', 'Loại 2: Rùa này nghe đồn là vật nuôi của Quy Lão, chắc là phải diệt khẩu chứ thả nó ra nó báo ông già là no đòn', 7861, 0, 1, 0, 0, 0, -1, -1, -1);
INSERT INTO `item_template` VALUES (1410, 37, 3, 'Cá lăng', 'Loại 4:Cá nhỏ, vảy cứng và sắc, thân bầu dục, màu sắc đẹp mắt, ăn không ngon nhưng bị săn lùng làm cá cảnh', 6982, 0, 1, 0, 0, 0, -1, -1, -1);
INSERT INTO `item_template` VALUES (1411, 38, 3, 'Cua tuyết', 'Loại 3: Động vật giáp xác, thân nhỏ, tuy bé nhưng rất nhiều gạch', 6571, 0, 1, 0, 0, 0, -1, -1, -1);
INSERT INTO `item_template` VALUES (1412, 39, 3, 'Hàu', 'Loại 2: Động vật thân mềm, sống tại vùng nước sạch, bám trên rạng đá ngầm. Ăn tái chanh thì ngon vcl', 6573, 0, 1, 0, 0, 0, -1, -1, -1);
INSERT INTO `item_template` VALUES (1413, 40, 3, 'Sao biển', ' Loại 4: Thân mềm, có gai, hơi khó sơ chế nhưng thịt khá ngon', 6572, 0, 1, 0, 0, 0, -1, -1, -1);
INSERT INTO `item_template` VALUES (1414, 75, 3, 'Ôc bươu', 'Loại 4: Ôc nhỏ, vỏ có gai, con này luộc xả chấm mắm gừng ăn ngon vcl', 6570, 0, 1, 0, 0, 0, -1, -1, -1);
INSERT INTO `item_template` VALUES (1415, 40, 3, 'Cá chép vây đỏ', 'Loại 1: Đầu dẹt, thân bầu dục , vảy cứng tỏa ra màu đỏ lấp lánh, tuy ngon nhưng không ai nỡ ăn mà thường sẽ để làm cá cảnh vì vẻ đẹp của nó', 4122, 0, 1, 0, 0, 0, -1, -1, -1);
INSERT INTO `item_template` VALUES (1416, 40, 3, 'Rương kho báu', 'Loại 1: Hòm vàng được trang trí điêu khắc rất tỉ mỉ, có vẻ sẽ có nhiều báu vật bên trong', 16174, 0, 1, 0, 0, 0, -1, -1, -1);
INSERT INTO `item_template` VALUES (1417, 39, 3, 'Rương vàng', 'Loại 2: Rương màu vàng này có vẻ là có kho báu chưa bên trong', 5007, 0, 1, 0, 0, 0, -1, -1, -1);
INSERT INTO `item_template` VALUES (1418, 38, 3, 'Rương bạc', 'Loại 3: Rương bạc này không biết có gì gia trị bên trong không nhỉ', 5006, 0, 1, 0, 0, 0, -1, -1, -1);
