INSERT INTO `posts` VALUES (13, 'Khai Mở Đua Top Open', '🔥 LIÊN MINH VŨ TRỤ– CHÍNH THỨC OPEN: 26/07/2025 – 20H00\r\n🎯 ĐẦY ĐỦ CÁC HỆ ĐIỀU HÀNH : TESTFLIGHT-ADR-PC-JAVA\r\n🔥 LOAN TIN NHẬN NGAY GIFTCODE CỰC XỊN ANH EM ƠI , CHỈ CẦN SHARE VÀO 3 GROUP GAME NHẮN NGAY CHO FANPAGE\r\n💚 Máy chủ cày chay như VIP – Chơi vui, không toxic!\r\n🎯 Chuỗi sự kiện đua top cực khủng – quà siêu to!\r\n🏆 SỰ KIỆN ĐUA TOP:\r\n⚔️ TOP SỨC MẠNH\r\n🥇 Top 1: 1000 TV, 1 LINH THÚ 30%, 500K VNĐ, 2000 Xu Vàng\r\n🥈 Top 2: 800 TV, 1 LINH THÚ 25%, 300K, 1500 Xu Vàng\r\n🥉 Top 3: 700 TV, 1 LINH THÚ 20%, 200K, 1000 Xu Vàng\r\n🎖️ Top 4–10: 200 TV, 500 Xu Vàng\r\n📜 TOP NHIỆM VỤ\r\n🥇 Top 1: 1000 TV,  300K VNĐ, 20 BỘ NGỌC RỒNG\r\n🥈 Top 2: 800 TV, 200K, 15 BỘ NGỌC RỒNG\r\n🥉 Top 3: 700 TV,  100K, 10 BỘ NGỌC RỒNG\r\n🎖️ Top 4–10: 200 TV, 3 BỘ NGỌC RỒNG\r\n💰 TOP NẠP\r\n👑 Top 1: 3000 TV, 1 RƯƠNG SKH TS , 3000 Xu Vàng, Broly Siêu VIP\r\n🥈 Top 2: 2000 TV,  1 RƯƠNG SKH TS , 2000 Xu Vàng, Broly VIP \r\n🥉 Top 3: 1000 TV,  1 RƯƠNG SKH TS , 1000 Xu Vàng, Broly VIP \r\n🎖️ Top 4–10: 500 TV, 500 TIỀN , 500 Xu Vàng\r\n🌐 THÔNG TIN LIÊN HỆ:\r\n🌍 Trang chủ: https://lienminhvutru.com\r\n💬 Box Zalo: https://zalo.me/g/iionqt841\r\n✅ Cày chay không thiệt – Quà to đầy tay!\r\n🎮 LIÊN MINH VŨ TRỤ – Nơi AE chơi vui, không gây gổ!\r\n💚 Không bug, không hút máu – chỉ chơi và nhận quà thật!', 'admin', '2025-08-02 17:57:35', 1, 0, NULL, 0, 0);
INSERT INTO `posts` VALUES (14, 'Sự Kiện Gắp Thú', '📢Thông báo Sự Kiện Gắp Thú X2 NẠP TIỀN\r\nTrong thời gian diễn ra sự kiện. Mỗi 1k người chơi nạp vào trong game sẽ nhận thêm 1 CS THƯỜNG\r\n200k trở lên nhận thêm 100 CS gắp thú tuỳ chọn ....\r\nHiện đang x2 exp tới 15/8\r\nSự kiện vòng quay diễn đến 20h 15/8\r\n🎁 QUÀ MỐC GẮP THÚ\r\n🔸 500 LẦN\r\n5 sao pha lê: 5% Sức đánh, 10% HP, 10% KI\r\n+ 50k VND\r\n50 xu sự kiện\r\n30 đá ngũ sắc\r\n50 tv \r\n10,000 hồng ngọc\r\n🔸 1000 LẦN\r\n8 sao pha lê: 5% Sức đánh, 10% HP, 10% KI\r\n+ 70k VND\r\n100 xu sự kiện\r\n50 đá ngũ sắc\r\n100 tv \r\n1 Hộp SKH thường\r\n20,000 hồng ngọc\r\n🔸 2000 LẦN\r\n12 sao pha lê: 5% Sức đánh, 10% HP, 10% KI\r\n+ 130k VND\r\n200 xu sự kiện\r\n70 đá ngũ sắc\r\n200 tv \r\n1 Hộp SKH thường\r\n40,000 hồng ngọc\r\n🔸 3000 LẦN\r\n18 sao pha lê: 5% Sức đánh, 10% HP, 10% KI\r\n+ 180k vnd\r\n300 xu sự kiện\r\n100 đá ngũ sắc\r\n300 tv \r\n1 bông tai cấp 4\r\n1 Món SKH Thần linh Max CS Tự Chọn\r\n60,000 hồng ngọc\r\n🔸 5000 VÒNG QUAY\r\n25 sao pha lê: 5% Sức đánh, 10% HP, 10% KI\r\n+ 250k VND\r\n500 xu sự kiện\r\n120 đá ngũ sắc\r\n380 tv \r\n1 Sách Tuyệt Kỹ (+20% chỉ số)\r\n2 Món SKH Thần linh Max CS Tự Chọn\r\n100,000 hồng ngọc\r\n🔸 7000 LẦN\r\n30 sao pha lê: 5% Sức đánh, 10% HP, 10% KI\r\n700 xu xự kiện\r\n150 đá ngũ sắc\r\n500 tv \r\nCapsule đệ tử Goku Bản năng vô cực\r\n2 Món SKH Hủy Diệt MAX CS Tự Chọn\r\n150,000 hồng ngọc\r\n🔸 10,000 VÒNG QUAY\r\n42 sao pha lê: 5% Sức đánh, 10% HP, 10% KI\r\n1000 xu sự kiện\r\n300 đá ngũ sắc\r\n1000 đá chân mệnh\r\nLinh thú tăng 30% chỉ số\r\n1 Hộp SKH Thiên sứ\r\n200,000 hồng ngọc\r\n🔸 15,000 VÒNG QUAY\r\n1200 xu sự kiện\r\n380 đá ngũ sắc\r\n1200 đá chân mệnh\r\n1 Hộp SKH Thiên sứ\r\n250,000 hồng ngọc\r\nCải trang Vegeta SSJ4\r\n🔸 20,000 VÒNG QUAY\r\n1500 xu sự kiện\r\n450 đá ngũ sắc\r\n1500 đá chân mệnh\r\n1 Hộp SKH Thiên sứ\r\n300,000 hồng ngọc\r\nCải trang Goku SSJ4\r\n🏆 QUÀ XẾP HẠNG VÒNG QUAY\r\n🎯 Điều kiện tham gia BXH: Người chơi phải đạt tối thiểu 1000 điểm vòng quay trở lên.\r\n🥇 TOP 1\r\n1 Hộp SKH Thiên sứ\r\n300 đá Khảm tự chọn\r\n3,000 thỏi vàng\r\nChân mệnh cấp 9: +35% chỉ số\r\n🥈 TOP 2\r\n2 Hộp SKH Thiên sứ\r\n200 đá Khảm tự chọn\r\n2,000 thỏi vàng\r\nChân mệnh cấp 9: +32% chỉ số\r\n🥉 TOP 3\r\n1 Hộp SKH Thiên sứ\r\n100 đá Khảm tự chọn\r\n1,000 thỏi vàng\r\nChân mệnh cấp 9: +30% chỉ số\r\n🏅 TOP 4 – 10\r\n1 Món SKH Hủy diệt\r\n500 thỏi vàng\r\n50 đá Khảm tự chọn\r\n100 đá ngũ sắc', 'admin', '2025-08-03 22:19:55', 1, 0, NULL, 0, 0);
